        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == 'isinstance' and len(node.args) == 2):
            return False
        second = node.args[1]
        if isinstance(second, ast.Name) and second.id == 'int':
            return True
        if isinstance(second, ast.Tuple):
            return any(isinstance(e, ast.Name) and e.id == 'int' for e in second.elts)
        return False

    def is_bool_check(node):
        # isinstance(x, bool)
        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == 'isinstance' and len(node.args) == 2):
            return False
        second = node.args[1]
        return isinstance(second, ast.Name) and second.id == 'bool'

    def arg_name(node):
        if isinstance(node, ast.Call) and len(node.args) >= 1:
            a = node.args[0]
            if isinstance(a, ast.Name):
                return a.id
        return None

    for func in ast.walk(tree):
        if not isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        # collect int-validation checks and bool checks in this function
        int_checks = []
        bool_checks = []
        for node in ast.walk(func):
            if isinstance(node, ast.Call):
                if is_int_check(node):
                    int_checks.append(node)
                elif is_bool_check(node):
                    bool_checks.append(node)
        if not int_checks:
            continue
        bool_args = {arg_name(n) for n in bool_checks}
        for ic in int_checks:
            name = arg_name(ic)
            if name is None:
                continue
            if name not in bool_args:
