        name = None
        if isinstance(func, ast.Name):
            name = func.id
        elif isinstance(func, ast.Attribute):
            name = func.attr
        return name in {"datetime", "now", "utcnow", "fromtimestamp", "fromisoformat", "strptime", "today"}

    def is_ensure_utc(node):
        if not isinstance(node, ast.Call):
            return False
        func = node.func
        if isinstance(func, ast.Name):
            return func.id == "ensure_utc"
        if isinstance(func, ast.Attribute):
            return func.attr == "ensure_utc"
        return False

    def is_datetime_typed(node):
        # Heuristic: a name/attribute that looks like a datetime value.
        if isinstance(node, ast.Name):
            return "dt" in node.id.lower() or "time" in node.id.lower() or "date" in node.id.lower()
        if isinstance(node, ast.Attribute):
            return is_datetime_typed(node.value)
        return False

    def is_normalized(node):
        if is_ensure_utc(node):
            return True
        if isinstance(node, ast.Call):
            # e.g. ensure_utc(x).something()
            return is_normalized(node.func)
        return False

    def check_operand(node, context):
        if is_datetime_call(node) or is_datetime_typed(node):
            if not is_normalized(node):
                violations.append(
                    "Normalize datetime with ensure_utc before %s" % context
                )

    for node in ast.walk(tree):
        if isinstance(node, ast.Compare):
            operands = [node.left] + list(node.comparators)
            for op in operands:
                check_operand(op, "comparing")
        elif isinstance(node, ast.BinOp):
            if isinstance(node.op, (ast.Add, ast.Sub)):
                check_operand(node.left, "arithmetic")
                check_operand(node.right, "arithmetic")

    # Deduplicate while preserving order
    seen = set()
    result = []
    for v in violations:
        if v not in seen:
            seen.add(v)
            result.append(v)
    return result

