def check(path: str, source: str) -> list[str]:
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []

    messages = []

    def is_money_name(name):
        return bool(re.search(r'(amount|price|cost|total|fee|balance|money|cents|subtotal|tax|discount)', name, re.I))

    def is_time_name(name):
        return bool(re.search(r'(time|timestamp|date|created|updated|at$|_at)', name, re.I))

    def call_name(node):
        if isinstance(node, ast.Call):
            f = node.func
            if isinstance(f, ast.Attribute):
                return f.attr
            if isinstance(f, ast.Name):
                return f.id
        return None

    def has_call(nodes, names):
        for n in nodes:
            for sub in ast.walk(n):
                if call_name(sub) in names:
                    return True
        return False

    def has_raise_billing_error(nodes):
        for n in nodes:
            for sub in ast.walk(n):
                if isinstance(sub, ast.Raise) and sub.exc is not None:
                    exc = sub.exc
                    if isinstance(exc, ast.Call):
                        exc = exc.func
                    if isinstance(exc, ast.Attribute) and exc.attr == 'BillingError':
                        return True
                    if isinstance(exc, ast.Name) and exc.id == 'BillingError':
                        return True
        return False

    for node in tree.body:
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        args = [a.arg for a in node.args.args + node.args.kwonlyargs]
        money_args = [a for a in args if is_money_name(a)]
        time_args = [a for a in args if is_time_name(a)]
        if not money_args and not time_args:
            continue

        body = node.body
        # skip docstring
        if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str):
            body = body[1:]

        if money_args:
            if not has_call(body, {'round_money'}):
                messages.append(f"{node.name}: money inputs not normalized with round_money")
            if not has_call(body, {'ZERO'}):
                messages.append(f"{node.name}: money inputs not normalized with ZERO")
        if time_args:
            if not has_call(body, {'ensure_utc'}):
                messages.append(f"{node.name}: timestamps not normalized with ensure_utc")

        if not has_raise_billing_error(body):
            messages.append(f"{node.name}: validation failures should raise BillingError")

    return messages

