                if is_audit_record(sub):
                    return True
        return False

    def audit_call_ok(call):
        # must have a past-tense string event as first positional arg
        if not call.args:
            return False
        first = call.args[0]
        if not (isinstance(first, ast.Constant) and isinstance(first.value, str)):
            return False
        if not re.match(r"^[a-z]+ed$", first.value):
            return False
        # must have payment_id=... or invoice_id=...
        kw_names = {kw.arg for kw in call.keywords if kw.arg}
        if not ({"payment_id", "invoice_id"} & kw_names):
            return False
        if "amount" not in kw_names:
            return False
        return True

    def has_valid_audit(nodes):
        for n in nodes:
            for sub in ast.walk(n):
                if is_audit_record(sub) and audit_call_ok(sub):
                    return True
        return False

    # Heuristic: functions that move money / change balances
    money_hints = re.compile(
        r"(pay|charge|refund|credit|debit|invoice|balance|adjust|transfer|settle|void|apply|reconcile|deposit|withdraw|reimburse)",
        re.IGNORECASE,
    )

