            if isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant):
                continue
        if not money_hints.search(name):
            continue
        if not has_valid_audit(body):
            messages.append(
                f"{name}: balance-changing operation must call ledgerly.audit.record(\"<past_tense_event>\", payment_id=... or invoice_id=..., amount=...)"
            )

    return messages

