    for func in [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]:
        # Find monetary parameters (annotated as money-ish) and assignments
        money_params = set()
        for arg in func.args.args + func.args.kwonlyargs:
            ann = arg.annotation
            if ann is not None:
                ann_src = ast.unparse(ann) if hasattr(ast, "unparse") else ""
                if "Money" in ann_src or "Decimal" in ann_src:
                    money_params.add(arg.arg)

        # Check comparisons against literal Decimal / numeric zero
        for node in ast.walk(func):
