        for node in ast.walk(func):
            if isinstance(node, ast.Assign):
                value = node.value
                # If assigning a raw numeric/Decimal literal to a money-ish target
                target_names = [t.id for t in node.targets if isinstance(t, ast.Name)]
                if not target_names:
                    continue
