                        msgs.append(
                            f"{func.name}: monetary input '{side.id}' used without to_money"
                        )

    # Deduplicate while preserving order
    seen = set()
    out = []
    for m in msgs:
        if m not in seen:
            seen.add(m)
            out.append(m)
    return out

