        if isinstance(func, ast.Name) and func.id == "ensure_utc":
            return True
        if isinstance(func, ast.Attribute) and func.attr == "ensure_utc":
            return True
        return False

    def is_datetime_expr(node):
        # Heuristic: a name/attribute/call that looks like a datetime value
        if isinstance(node, ast.Call):
            f = node.func
            name = None
            if isinstance(f, ast.Name):
                name = f.id
            elif isinstance(f, ast.Attribute):
                name = f.attr
            if name in ("now", "utcnow", "fromtimestamp", "fromisoformat", "strptime", "today"):
                return True
            return False
        if isinstance(node, ast.Name):
            return "time" in node.id.lower() or "date" in node.id.lower() or node.id.lower().endswith("_at")
        if isinstance(node, ast.Attribute):
            return "time" in node.attr.lower() or "date" in node.attr.lower() or node.attr.lower().endswith("_at")
        return False

    def is_normalized(node):
        if is_ensure_utc_call(node):
            return True
        if isinstance(node, ast.Call):
            # e.g. ensure_utc(x).something()
            return is_normalized(node.func)
        return False

    for func in ast.walk(tree):
        if not isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        for node in ast.walk(func):
            operands = []
            if isinstance(node, ast.Compare):
                operands = [node.left] + list(node.comparators)
            elif isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Sub, ast.Add)):
                operands = [node.left, node.right]
            for op in operands:
                if is_datetime_expr(op) and not is_normalized(op):
                    violations.append(
                        "Normalize datetime with ensure_utc before comparing or doing arithmetic"
                    )
                    break

    # Deduplicate while preserving order
    seen = set()
    result = []
    for v in violations:
        if v not in seen:
            seen.add(v)
            result.append(v)
    return result

