def _first_statement_checks_key(fn: ast.FunctionDef) -> bool:
    """Check that the function consults audit.events() for the key before
    doing state validation."""
    body = fn.body
    # Skip a leading docstring.
    if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \
            and isinstance(body[0].value.value, str):
        body = body[1:]
    if not body:
        return False
    # Find the first statement that references audit.events() and idempotency_key.
    for stmt in body:
        src = ast.dump(stmt)
        if "events" in src and "idempotency_key" in src:
            return True
        # If we hit a state-validation-looking statement first, fail.
        if isinstance(stmt, (ast.If, ast.Assert, ast.Raise)):
            # allow if it's the idempotency check itself
            if "idempotency_key" in src:
                return True
            return False
    return False


