                        if not (isinstance(operand, ast.Call) and isinstance(operand.func, ast.Name) and operand.func.id == 'Decimal'):
                            if not is_decimal_str_call(operand):
                                messages.append("Decimal multiplied/divided by non-Decimal; convert via Decimal(str(x))")
                                break

    return messages
